customCSS:
.t, .history { color: #636da6; }
.join { color: #c3e88d; }
.part, .quit { color: #636da6; }
.kick, .error { color: #ff757f; }
.notice { color: #ffc777; }
.action { color: #c099ff; }
.mode, .nick, .topic, .server { color: #86e1fc; }
.highlight { color: #c8d3f5; background-color: #2d3f76; border-left: 3px solid #c099ff; padding-left: 8px; }
.reply { color: #636da6; border-left: 2px solid #82aaff; padding-left: 6px; }
.oper { color: #222436; background-color: #ffc777; }
.reactions { color: #82aaff; background-color: #1b1d2b; }
.card { background-color: #1b1d2b; border-color: #636da6; }
.card-title { color: #82aaff; }
.card-desc { color: #636da6; }
.daychange { color: #636da6; border-color: #1b1d2b; }
